const fs = require('fs');

const input = $input.first().json;
const body = input.body || input;
const alerts = Array.isArray(body.alerts) ? body.alerts : [];
const alert = alerts[0] || {};
const labels = alert.labels || body.commonLabels || {};
const annotations = alert.annotations || body.commonAnnotations || {};

const status = String(alert.status || body.status || 'firing').toLowerCase();
const alertName = labels.alertname || 'PatroniMasterFailover';
const cluster = labels.cluster || 'gamer-postgres';
const nowIso = new Date().toISOString();

// 1. Solo procesar alertas en estado firing (descartar resolved)
if (status !== 'firing') {
  return [{
    json: {
      capture: false,
      reason: `Alerta ignorada porque su estado es '${status}' (solo se procesa 'firing').`,
      alertName,
      status,
      timestamp: nowIso
    }
  }];
}

// 2. Enriquecer con estado real del clúster (Patroni REST API + Prometheus)
let promotedNode = labels.name || 'Desconocido';
let fallenNode = 'Desconocido';
let timeline = 'N/A';
let clusterMembers = [];

const patroniNodes = ['pg-node-1', 'pg-node-2', 'pg-node-3'];
for (const node of patroniNodes) {
  try {
    const data = await this.helpers.httpRequest({
      method: 'GET',
      url: `http://${node}:8008/cluster`,
      json: true,
      timeout: 3000
    });
    if (data && Array.isArray(data.members) && data.members.length > 0) {
      clusterMembers = data.members;
      const leader = data.members.find(m => m.role === 'leader' || m.role === 'master');
      if (leader) {
        promotedNode = leader.name || promotedNode;
        if (leader.timeline !== undefined) timeline = String(leader.timeline);
      }
      const aliveNames = new Set(data.members.map(m => m.name));
      const missing = patroniNodes.filter(n => !aliveNames.has(n));
      if (missing.length > 0) {
        fallenNode = missing.join(', ');
      }
      break;
    }
  } catch (e) {
    // El nodo puede estar caído, continuar con el siguiente
  }
}

// Si el nodo caído ya se reincorporó, consultarlo en Prometheus (quién estuvo down o quién era primario hace 3m)
if (fallenNode === 'Desconocido') {
  try {
    const promRes = await this.helpers.httpRequest({
      method: 'GET',
      url: 'http://prometheus:9090/api/v1/query?query=' + encodeURIComponent('min_over_time(up{job="patroni-cluster"}[5m]) == 0'),
      json: true,
      timeout: 3000
    });
    const results = promRes?.data?.result || [];
    if (results.length > 0) {
      fallenNode = results.map(r => (r.metric.instance || '').split(':')[0]).filter(Boolean).join(', ');
    }
  } catch (e) {}
}

if (fallenNode === 'Desconocido') {
  try {
    const promPrev = await this.helpers.httpRequest({
      method: 'GET',
      url: 'http://prometheus:9090/api/v1/query?query=' + encodeURIComponent('max_over_time(patroni_primary{cluster="gamer-postgres"}[5m]) == 1'),
      json: true,
      timeout: 3000
    });
    const prevLeaders = (promPrev?.data?.result || [])
      .map(r => r.metric.name)
      .filter(n => n && n !== promotedNode);
    if (prevLeaders.length > 0) {
      fallenNode = prevLeaders.join(', ');
    }
  } catch (e) {}
}

// 3. Candado atómico (O_CREAT | O_EXCL): CAPTURAR SOLAMENTE EL 1ER EVENTO
const lockPath = '/home/node/.n8n/failover_evento_1.lock';
let fd = null;
try {
  fd = fs.openSync(lockPath, 'wx');
  const lockPayload = {
    eventNumber: 1,
    capturedAt: nowIso,
    alertName,
    cluster,
    fallenNode,
    promotedNode,
    timeline
  };
  fs.writeFileSync(fd, JSON.stringify(lockPayload, null, 2), 'utf8');
  fs.closeSync(fd);
} catch (err) {
  if (fd !== null) {
    try { fs.closeSync(fd); } catch (_) {}
  }
  if (err && err.code === 'EEXIST') {
    let previousEvent = {};
    try {
      previousEvent = JSON.parse(fs.readFileSync(lockPath, 'utf8'));
    } catch (_) {}
    return [{
      json: {
        capture: false,
        eventIgnored: true,
        reason: 'Ya se capturó el 1er evento de failover. Los eventos posteriores (2do, 3ro, 4to, etc.) o duplicados se descartan.',
        firstEvent: previousEvent,
        discardedAt: nowIso
      }
    }];
  }
  throw err;
}

// 4. Formatear resumen del clúster y datos del ticket GLPI (solo para el 1er evento)
const clusterSummary = clusterMembers.length > 0
  ? clusterMembers.map(m => `- ${m.name}: rol=${m.role}, estado=${m.state}, timeline=${m.timeline}`).join('\n')
  : 'No se pudo consultar la lista completa de miembros de Patroni.';

const summary = annotations.summary || `Failover Patroni: caída de ${fallenNode} y promoción de ${promotedNode} a maestro`;
const description = annotations.description || `Se detectó la caída del nodo maestro (${fallenNode}) en el clúster ${cluster} y la promoción automática del nodo esclavo ${promotedNode} a maestro (timeline ${timeline}).`;

const ticketTitle = `[CRÍTICO - EVENTO #1] Failover Patroni: caída de ${fallenNode} y promoción de ${promotedNode}`;
const ticketContent = [
  '<b>Reporte automático único (1er evento de failover capturado por n8n)</b><br><br>',
  `<b>Evento:</b> Caída de nodo maestro y promoción de nodo esclavo a maestro<br>`,
  `<b>Alerta Prometheus:</b> ${alertName}<br>`,
  `<b>Clúster:</b> ${cluster}<br>`,
  `<b>Nodo maestro caído:</b> ${fallenNode}<br>`,
  `<b>Nodo esclavo promovido a maestro:</b> ${promotedNode}<br>`,
  `<b>Timeline actual:</b> ${timeline}<br>`,
  `<b>Severidad:</b> ${labels.severity || 'critical'}<br>`,
  `<b>Detalle:</b> ${description}<br>`,
  `<b>Estado actual del clúster:</b><br><pre>${clusterSummary}</pre>`,
  `<b>Fecha/Hora (UTC):</b> ${nowIso}<br><br>`,
  '<i>Nota: Se iniciará automáticamente el proceso RAG sobre la documentación en Nextcloud para generar e insertar el archivo solucion_1.md.</i>'
].join('');

const ragQuery = `Failover automático PostgreSQL Patroni caída de nodo maestro ${fallenNode} promoción de nodo esclavo ${promotedNode} a maestro líder etcd HAProxy pg_rewind recuperación reincorporación patronictl`;

return [{
  json: {
    capture: true,
    eventNumber: 1,
    alertName,
    cluster,
    fallenNode,
    promotedNode,
    timeline,
    clusterSummary,
    severity: labels.severity || 'critical',
    urgency: 5,
    status,
    summary,
    description,
    ticketTitle,
    ticketContent,
    ragQuery,
    timestamp: nowIso
  }
}];

