const resp = $input.first().json;
const entries = resp?.ocs?.data?.entries || [];

// Excluir carpetas demo de Nextcloud y archivos de solución previos
const excludedPrefixes = ['/Templates/', '/Photos/', '/Documents/'];
const excludedNames = new Set(['Readme.md', 'Templates credits.md', 'solucion_1.md']);

const docs = [];
for (const entry of entries) {
  const filePath = entry?.attributes?.path;
  const title = entry?.title || '';
  if (!filePath || !filePath.toLowerCase().endsWith('.md')) continue;
  if (excludedPrefixes.some(p => filePath.startsWith(p))) continue;
  if (excludedNames.has(title)) continue;
  if (title.toLowerCase().startsWith('solucion_')) continue;

  const encodedPath = filePath
    .split('/')
    .map(seg => encodeURIComponent(seg))
    .join('/');

  docs.push({
    json: {
      title,
      path: filePath,
      folder: entry.subline || '',
      fileId: entry?.attributes?.fileId || '',
      webdavUrl: `http://nextcloud/remote.php/dav/files/admin_nextcloud${encodedPath}`
    }
  });
}

if (docs.length === 0) {
  throw new Error('No se encontraron archivos Markdown del proyecto en Nextcloud para aplicar RAG.');
}

return docs;

const GEMINI_API_KEY = 'TU_API_KEY';
const EMBED_MODELS = ['models/gemini-embedding-001', 'models/gemini-embedding-2'];

const downloadedItems = $input.all();
const docMetaItems = $('Filtrar Documentos Nextcloud').all();
const eventData = $('Filtrar 1er Evento y Enriquecer').first().json;
const glpiResp = $('GLPI - Crear Ticket Failover').first().json || {};
const glpiTicketId = glpiResp.id || 'N/A';

// 1. Chunking con solapamiento preservando fuente de Nextcloud
function splitIntoChunks(text, source, title, maxChars = 1500, overlap = 200) {
  const clean = String(text || '').replace(/\r\n/g, '\n').trim();
  if (!clean) return [];
  const chunks = [];
  let start = 0;
  let idx = 0;
  while (start < clean.length) {
    let end = Math.min(start + maxChars, clean.length);
    if (end < clean.length) {
      const breakPos = clean.lastIndexOf('\n\n', end);
      if (breakPos > start + Math.floor(maxChars * 0.5)) {
        end = breakPos;
      } else {
        const nlPos = clean.lastIndexOf('\n', end);
        if (nlPos > start + Math.floor(maxChars * 0.5)) end = nlPos;
      }
    }
    const slice = clean.slice(start, end).trim();
    if (slice.length > 40) {
      chunks.push({ source, title, chunkIndex: idx++, text: slice });
    }
    if (end >= clean.length) break;
    start = Math.max(end - overlap, start + 1);
  }
  return chunks;
}

const allChunks = [];
let loadedDocs = 0;
for (let i = 0; i < downloadedItems.length; i++) {
  const raw = downloadedItems[i]?.json?.data;
  const meta = docMetaItems[i]?.json || {};
  if (typeof raw === 'string' && raw.trim().length > 0) {
    loadedDocs++;
    const chunks = splitIntoChunks(raw, meta.path || `doc_${i}`, meta.title || `doc_${i}`);
    allChunks.push(...chunks);
  }
}

if (allChunks.length === 0) {
  throw new Error('No se pudo extraer contenido de texto de los archivos descargados de Nextcloud.');
}

// 2. Etapa 1 RAG Híbrido: Pre-ranking léxico (BM25 simplificado) sobre todos los chunks para seleccionar Top-15 candidatos
function tokenize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9_\-]+/g, ' ')
    .split(/\s+/)
    .filter(w => w.length >= 2);
}

const queryTokens = tokenize(eventData.ragQuery);
const docFreq = new Map();
const chunkTokensList = allChunks.map(c => {
  const toks = tokenize(`${c.source} ${c.title} ${c.text}`);
  const unique = new Set(toks);
  for (const t of unique) docFreq.set(t, (docFreq.get(t) || 0) + 1);
  return toks;
});
const avgLen = chunkTokensList.reduce((acc, t) => acc + t.length, 0) / Math.max(1, chunkTokensList.length);
const N = allChunks.length;

const bm25Scored = allChunks.map((chunk, i) => {
  const toks = chunkTokensList[i];
  const tfMap = new Map();
  for (const t of toks) tfMap.set(t, (tfMap.get(t) || 0) + 1);
  let score = 0;
  const k1 = 1.5, b = 0.75;
  for (const qt of queryTokens) {
    const tf = tfMap.get(qt) || 0;
    if (!tf) continue;
    const df = docFreq.get(qt) || 0;
    const idf = Math.log(1 + (N - df + 0.5) / (df + 0.5));
    score += idf * ((tf * (k1 + 1)) / (tf + k1 * (1 - b + b * (toks.length / avgLen))));
  }
  return { ...chunk, bm25: score };
});

bm25Scored.sort((a, b) => b.bm25 - a.bm25);
const CANDIDATE_K = Math.min(15, bm25Scored.length);
const candidates = bm25Scored.slice(0, CANDIDATE_K);
const maxBm25 = Math.max(1e-9, ...candidates.map(c => c.bm25));

// 3. Etapa 2 RAG Híbrido: Embeddings vectoriales densos con Gemini + Similitud Coseno
function cosineSimilarity(a, b) {
  if (!a.length || a.length !== b.length) return 0;
  let dot = 0, normA = 0, normB = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }
  const denom = Math.sqrt(normA) * Math.sqrt(normB);
  return denom === 0 ? 0 : dot / denom;
}

let usedEmbedModel = 'bm25-fallback';
let ranked = null;

for (const modelName of EMBED_MODELS) {
  try {
    const batchResp = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://generativelanguage.googleapis.com/v1beta/${modelName}:batchEmbedContents?key=${GEMINI_API_KEY}`,
      headers: { 'Content-Type': 'application/json' },
      body: {
        requests: [
          { model: modelName, content: { parts: [{ text: eventData.ragQuery }] } },
          ...candidates.map(c => ({
            model: modelName,
            content: { parts: [{ text: `Documento: ${c.source}\n\n${c.text}` }] }
          }))
        ]
      },
      json: true
    });
    const embs = batchResp?.embeddings || [];
    if (embs.length === candidates.length + 1) {
      const queryVec = embs[0].values || [];
      usedEmbedModel = modelName;
      ranked = candidates.map((c, idx) => {
        const cos = cosineSimilarity(queryVec, embs[idx + 1].values || []);
        const bm25Norm = c.bm25 / maxBm25;
        return { ...c, cosine: cos, score: 0.75 * cos + 0.25 * bm25Norm };
      });
      ranked.sort((a, b) => b.score - a.score);
      break;
    }
  } catch (err) {
    // Si un modelo da 429/cuota, intenta el siguiente modelo automáticamente
  }
}

if (!ranked) {
  ranked = candidates.map(c => ({ ...c, cosine: 0, score: c.bm25 / maxBm25 }));
}

const TOP_K = Math.min(6, ranked.length);
const topChunks = ranked.slice(0, TOP_K);

const retrievedContext = topChunks.map((c, idx) =>
  `### Fragmento ${idx + 1} | Archivo Nextcloud: ${c.source} | Relevancia RAG: ${(c.score * 100).toFixed(1)}% (coseno: ${(c.cosine * 100).toFixed(1)}%)\n${c.text}`
).join('\n\n---\n\n');

const topSourcesSummary = topChunks.map(c =>
  `- \`${c.source}\` (chunk #${c.chunkIndex + 1}, relevancia ${(c.score * 100).toFixed(1)}%, coseno ${(c.cosine * 100).toFixed(1)}%)`
).join('\n');

// 4. Construir prompt RAG aumentado con la documentación recuperada de Nextcloud
const prompt = `Actúa como un Ingeniero Senior de Confiabilidad de Sitios (SRE) y Administrador de Bases de Datos PostgreSQL/Patroni.

Se produjo el PRIMER evento de failover automático en la plataforma "Red Social Gamer" y ya fue reportado en GLPI.
Debes generar el documento oficial "Solución 1" en formato Markdown limpio y profesional, basándote EXCLUSIVAMENTE en los datos reales del incidente y en los fragmentos de documentación recuperados mediante RAG desde Nextcloud.

## Datos reales del Incidente (Evento #1)
- Ticket GLPI creado: #${glpiTicketId}
- Alerta Prometheus: ${eventData.alertName}
- Clúster afectado: ${eventData.cluster}
- Nodo maestro caído: ${eventData.fallenNode}
- Nodo esclavo promovido a maestro (Leader): ${eventData.promotedNode}
- Timeline actual de PostgreSQL: ${eventData.timeline}
- Fecha/Hora del evento (UTC): ${eventData.timestamp}
- Estado observado del clúster:
${eventData.clusterSummary}

## Contexto Documental Recuperado por RAG desde Nextcloud (Top ${TOP_K} fragmentos más relevantes)
${retrievedContext}

## Estructura obligatoria del documento "Solución 1" (Markdown)
1. **Título**: \`# Solución 1 — Recuperación ante Caída de Nodo Maestro y Promoción de Esclavo (${eventData.cluster})\`
2. **Resumen del Incidente (Evento #1)**: Datos del nodo maestro caído (${eventData.fallenNode}), nodo esclavo promovido (${eventData.promotedNode}), timeline (${eventData.timeline}), y referencia al Ticket GLPI #${glpiTicketId}.
3. **Análisis Técnico del Failover**: Explicación basada en la documentación recuperada (rol de Patroni, bloqueo de liderazgo en etcd, enrutamiento de HAProxy por \`/primary\`, replicación síncrona y comportamiento del backend Express).
4. **Procedimiento Paso a Paso de Solución y Reincorporación**: Comandos exactos adaptados a los nodos reales del incidente (${eventData.fallenNode} y ${eventData.promotedNode}): verificación con \`patronictl\`, revisión de logs/estado, arranque del nodo caído con \`docker compose start ${eventData.fallenNode}\`, validación de \`pg_rewind\` y reincorporación como réplica en streaming, contingencia con \`patronictl reinit\` si hubiese divergencia, y validación de lectura/escritura por HAProxy y API.
5. **Verificación Post-Recuperación y Checklist de Cierre de Ticket GLPI #${glpiTicketId}**.
6. **Fuentes Documentales de Nextcloud Utilizadas (RAG)**: Listado de los documentos recuperados.

No inventes procedimientos que contradigan la documentación recuperada. Responde directamente con el contenido Markdown listo para guardar como \`solucion_1.md\`.`;

return [{
  json: {
    prompt,
    glpiTicketId,
    fallenNode: eventData.fallenNode,
    promotedNode: eventData.promotedNode,
    timeline: eventData.timeline,
    timestamp: eventData.timestamp,
    totalDocs: loadedDocs,
    totalChunks: allChunks.length,
    candidatesEmbedded: candidates.length,
    embedModel: usedEmbedModel,
    topK: topChunks.length,
    topSourcesSummary
  }
}];

