const response = $input.first().json;
const ragMeta = $('RAG - Embeddings y Busqueda Semantica').first().json;

let solutionMarkdown = '';
try {
  solutionMarkdown = response.candidates[0].content.parts[0].text;
} catch (e) {
  solutionMarkdown = `# Solución 1 — Error al generar con Gemini AI\n\nDetalle: ${e.message}`;
}

const footer = [
  '',
  '---',
  '## Trazabilidad del Flujo Automatizado (n8n + RAG)',
  `- **Evento capturado:** #1 (único evento procesado; eventos 2do, 3ro, 4to+ bloqueados)`,
  `- **Ticket GLPI:** #${ragMeta.glpiTicketId}`,
  `- **Nodo maestro caído:** \`${ragMeta.fallenNode}\``,
  `- **Nodo esclavo promovido:** \`${ragMeta.promotedNode}\``,
  `- **Timeline:** ${ragMeta.timeline}`,
  `- **Documentos analizados en Nextcloud:** ${ragMeta.totalDocs} archivos (${ragMeta.totalChunks} chunks totales, Top-${ragMeta.candidatesEmbedded} vectorizados con \`${ragMeta.embedModel}\`)`,
  `- **Top-${ragMeta.topK} fragmentos recuperados por similitud coseno:**`,
  ragMeta.topSourcesSummary,
  `- **Generado el (UTC):** ${new Date().toISOString()}`
].join('\n');

const fullContent = `${solutionMarkdown.trim()}\n${footer}\n`;

return [{
  json: {
    filename: 'solucion_1.md',
    solutionContent: fullContent,
    glpiTicketId: ragMeta.glpiTicketId,
    tamanoChars: fullContent.length
  }
}];
